// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // Fuzz the caller and some other params; the key deciding value is the _tos array length = 0 case
    function testFuzz_property(address from, address caddress, uint256 v, uint256 _decimals) public {
        // Keep addresses non-zero to be in wide admissible domain
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        // We will test the universal property: when the _tos array is empty, reference MUST revert.
        address[] memory empty = new address[](0);

        bool ok;
        // call and capture whether it reverts
        try c.transfer(from, caddress, empty, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: reference contract ALWAYS reverts (ok == false) for empty _tos; the mutant that removed the require will make ok == true for some inputs
        assertTrue(!ok);
    }
}
